(function(root){
 const questions=[];let ordinal=0;function q(id,topic,kind,prompt,options,explanation){const shift=ordinal++%options.length;questions.push({id,topic,kind,prompt,options:[...options.slice(shift),...options.slice(0,shift)],answer:(options.length-shift)%options.length,explanation});}
 const methods={resultants:'Resolve and add signed components',position:'Build displacement, normalize, then scale',projection:'Dot product with a unit direction',moments:'Position crossed with force',axis:'Cross product followed by an axis projection',couples:'Separation crossed with one force',systems:'Sum forces and moments about one reference',location:'Match the resultant force and moment',distributed:'Integrate intensity and its first moment',integrals:'Find an antiderivative and evaluate bounds'};
 const prompts={resultants:'Several concurrent forces have known magnitudes and directions. You need their net force.',position:'A cable pulls from one known point toward another, and its tension is given.',projection:'You need the signed part of a force along a specified rod.',moments:'A force acts at a known point. You need its turning effect about O.',axis:'A force acts on a member. You need the twist about an inclined shaft.',couples:'Equal, opposite, parallel forces act on different lines. You need their net turning effect.',systems:'Several forces and applied couples must be replaced at a specified point O.',location:'You know the resultant force and total moment and must locate an equivalent single force.',distributed:'A beam carries a varying load intensity w(x). You need the equivalent force and its location.',integrals:'You need the accumulated value of a continuous function over a stated interval.'};
 for(const [topic,method] of Object.entries(methods)){const wrong=Object.values(methods).filter(x=>x!==method);q('method-'+topic,topic,'method',prompts[topic],[method,wrong[0],wrong[3]],'Choose '+method.toLowerCase()+'. Identify what is given and whether the requested answer is a force, moment, component, or accumulated value.');}
 q('method-angle','projection','method','Two nonzero 3D vectors are given in Cartesian form. Find the angle between them.',['Normalize the dot product, then use inverse cosine','Cross them and report the vector as the angle','Subtract their magnitudes'],'cos θ = (A·B)/(|A||B|). Inverse cosine returns the included angle from 0 to 180° in DEGREE mode.');
 q('method-perp','moments','method','A force magnitude and its true perpendicular distance to O are already known. Find moment magnitude.',['Multiply F by the perpendicular distance','Normalize the force and stop','Use force times the full distance to its application point'],'|M| = Fd is the direct scalar method when d is already perpendicular. Determine rotational sign separately.');
 q('error-direction','position','error','A = (1,1,0), B = (4,5,0). A solution says rAB = A − B = (−3,−4,0). What needs correcting?',['Use B − A for the direction A→B','Divide by 100 N','Nothing; direction does not depend on endpoint order'],'A→B means ending point minus starting point, so rAB = (3,4,0). The negative vector points B→A.');
 q('error-unit','projection','error','A student projects F onto d = (3,4,0) using F·d. What is the error?',['Normalize d to unit length before taking the dot product','The dot product must always be negative','All three components of d must be nonzero'],'A signed projection is F·u, with |u| = 1. Here u = (0.6,0.8,0).');
 q('error-cross','moments','error','A solution uses F × r for the moment of F about O. Which correction is needed?',['Use r × F; the reversed order changes the sign','Use F·r instead','Keep the order but remove all negative components'],'Moment is r × F, with r starting at O and ending on the force line. Cross products are anticommutative.');
 q('error-axis','axis','error','A student calculates |r×F| and reports it as the moment about an inclined axis. What is missing?',['Project the point moment onto the unit axis','Add the force magnitude','Multiply by the axis length'],'The axis moment is uaxis·(r×F), not generally the magnitude of the full moment vector.');
 q('error-couple','couples','error','Two equal opposite 100 N forces have perpendicular separation 0.4 m. A solution uses 2(100)(0.4). What is wrong?',['Use one force times the line separation','The forces cancel every rotational effect','The separation must be squared'],'A couple magnitude is Fd = 40 N·m. The separation already accounts for the two lines of action; do not double F.');
 q('error-sum','resultants','error','Forces of 30 N and 40 N act at right angles. A solution reports a 70 N resultant. What should change?',['Add components or use the perpendicular-vector magnitude','Average the two magnitudes','Keep 70 N for every included angle'],'For perpendicular forces, magnitude is √(30²+40²) = 50 N. Adding magnitudes applies to aligned forces pointing the same way.');
 q('error-transfer','systems','error','A force is moved sideways to O with no added couple. Is the system still equivalent?',['Usually no; add the transfer couple r×F','Yes, forces may move to any point freely','Only if its magnitude is doubled'],'Moving along a force’s line preserves its moment. Moving off that line requires a compensating couple.');
 q('error-location','location','error','A system has zero resultant force and a nonzero moment. A solution divides moment by zero force to find x. What should it report?',['A pure couple, with no finite single-force location','x = 0 automatically','No external loading'],'A single nonzero force cannot represent zero net force plus nonzero moment. Keep the equivalent couple.');
 q('error-centroid','distributed','error','A triangular load rises from zero at x=0 to its maximum at x=L. A solution places its resultant at L/3 from x=0. What is wrong?',['It should be 2L/3 from the zero end','It must always be at L/2','The resultant has no location'],'The centroid lies closer to the larger intensity: 2L/3 from the zero end, or L/3 from the maximum end.');
 q('error-bounds','integrals','error','To evaluate ∫₁³ 2x dx, a solution subtracts f(3) − f(1). What should it use?',['F(3) − F(1), where F is an antiderivative','f(3) + f(1)','The derivative of f at x=3'],'F(x)=x² is an antiderivative, so the integral is 9−1 = 8. Use antiderivative values, not integrand heights.');
 q('error-power','integrals','error','A solution writes ∫x² dx = x³/2 + C. Which correction is needed?',['Divide by the new exponent 3','Keep exponent 2 and divide by 3','Remove C to fix the coefficient'],'The power rule adds one to the exponent and divides by that new exponent: x³/3 + C. Differentiate to verify.');
 q('ti-negative','resultants','calculator','On a TI-84 Plus, how should you enter the square of a negative component −30?',['Use (−30)^2, entering the negative with [(-)]','Use −30^2 without parentheses','Enter −(30^2) as the positive square'],'Parentheses keep the signed component together. (−30)^2 = 900; −30^2 = −900 under standard precedence.');
 q('ti-mode','projection','calculator','You are evaluating 100cos(60°) for a statics component. What setup is appropriate?',['DEGREE mode, then 100*cos(60)','RADIAN mode, then 100*cos(60)','Mode does not affect trigonometry'],'Use DEGREE when entering 60 as a degree value. In standard calculus trig examples involving π, use RADIAN instead.');
 q('ti-memory','position','calculator','A unit-vector component displays 0.2307692308. How should you use it to calculate a later force component?',['Use its full-precision stored variable','Retype 0.23','Round it to the final significant figures now'],'STO→ keeps the calculator’s internal value. Round the final reported result rather than intermediate components.');
 q('ti-integral','integrals','calculator','Which TI-84 Classic-mode entry evaluates ∫₀² 3X² dX numerically?',['fnInt(3*X^2,X,0,2)','fnInt(3*X^2,0,2,X)','nDeriv(3*X^2,X,2)'],'fnInt(expression,variable,lower,upper) evaluates a definite integral numerically. It does not return a symbolic antiderivative.');
 const diagrams=[{id:'diagram-positive',topic:'position',kind:'diagram',A:[1,1,0],B:[4,5,0],answer:[3,4,0]},{id:'diagram-negative',topic:'position',kind:'diagram',A:[3,2,0],B:[-1,4,0],answer:[-4,2,0]},{id:'diagram-3d',topic:'position',kind:'diagram',A:[1,-2,1],B:[4,2,5],answer:[3,4,4]},{id:'diagram-reverse',topic:'position',kind:'diagram',A:[4,5,0],B:[1,1,0],answer:[-3,-4,0]}];
 const equations=[['components','Components','Fx = F cos θ; Fy = F sin θ','θ measured from +x; perpendicular xy axes.'],['vector','Directed force','rAB = B − A; uAB = rAB/|rAB|; F = |F|uAB','Distinct endpoints; u points in the force direction.'],['magnitude','Magnitude','|V| = √(Vx² + Vy² + Vz²)','Perpendicular Cartesian axes.'],['direction','Direction','θ = tan⁻¹(Ry/Rx), with quadrant correction','Rx<0: add 180°; Rx>0,Ry<0: add 360°. Handle Rx=0 separately.'],['projection','Projection','Faxis = F·u; Fparallel = Faxis u','|u| = 1; scalar is signed.'],['angle','Included angle','cos θ = (A·B)/(|A||B|)','Both vectors nonzero.'],['moment','Moment','M = r×F; Mz = rx Fy − ry Fx','r begins at the requested reference.'],['axis','Axis moment','Ma = ua·(r×F)','Reference lies on axis; ua is unit length.'],['couple','Couple','Mc = (P−Q)×F; |Mc| = Fd','+F at P, −F at Q; d is perpendicular separation.'],['system','Equivalent system','R = ΣF; MO = Σ(r×F) + ΣC','All moments use the same O; couples add directly.'],['location','Resultant location','r×R = MO; y=0 ⇒ x Ry = Mz','Only divide when the relevant force component is nonzero.'],['load','Distributed load','FR = ∫w dx; Q = ∫xw dx; x̄ = Q/FR','Use the same origin and bounds; FR≠0 for location.'],['shapes','Simple load shapes','Uniform: FR=wL, x̄=L/2; triangle: FR=wmax L/2','Increasing triangle: x̄=2L/3 from zero end.'],['power','Power rule','∫c xⁿ dx = c xⁿ⁺¹/(n+1) + C','n≠−1; ∫dx/x=ln|x|+C away from zero.'],['bounds','Bounds','∫ₐᵇ f dx = F(b)−F(a)','F′=f; check domain and singularities.'],['substitution','Substitution / parts','u=g(x), du=g′(x)dx; ∫u dv=uv−∫v du','Change bounds with the variable, or restore x before evaluation.']].map(([id,title,formula,conditions])=>({id,title,formula,conditions}));
 const entries=[{id:'entry-component',topic:'resultants',kind:'entry',prompt:'Construct a TI-style entry for the x component of a 100 N force at 60° from +x. Use cos(...) in typed input.',mode:'DEG',required:'cos',value:50,example:'100*cos(60)'},{id:'entry-negative',topic:'moments',kind:'entry',prompt:'Construct an entry for the square of a component −30. In typed input, use - to represent the TI-84 [(-)] key.',negative:true,value:900,example:'(-30)^2'},{id:'entry-quadrant',topic:'resultants',kind:'entry',prompt:'F = (−60,80,0) N. Construct the 0–360° direction using atan(...) and a quadrant correction.',mode:'DEG',required:'atan',value:126.86989764584402,example:'atan(80/(-60))+180'},{id:'entry-bounds',topic:'integrals',kind:'entry',prompt:'An antiderivative of X² is X³/3. Construct the full upper-minus-lower entry for bounds 0 to 2.',value:8/3,example:'(2^3/3)-(0^3/3)'}];
 const api={questions,diagrams,entries,equations,methods};root.StudyData=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
